UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "All": {
        "Claimed": "select task.name_ as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN task.assignee_ is not null THEN oplog.create_time_ ELSE null END  as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as  \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" , null as  \\"Closed By\\"  from camunda.act_ru_task task left join  camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_ left join camunda.act_id_user cuser on task.assignee_=cuser.id_ left join camunda.act_hi_varinst oplog on oplog.id_ = (select id_ from camunda.act_hi_varinst where proc_inst_id_ = task.proc_inst_id_ and name_ = ''userActivity'' and var_type_ = ''string'' order by create_time_ desc limit 1) left join camunda.act_ru_variable payer on payer.proc_inst_id_ = task.proc_inst_id_ and payer.name_ = ''payer'' and payer.type_ = ''string'' left join camunda.act_ru_variable payee on payee.proc_inst_id_ = task.proc_inst_id_ and payee.name_ = ''payee'' and payee.type_ = ''string'' left join camunda.act_ru_variable  TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' and TransactionAmount.type_ = ''double'' left join  camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' and TicketID.type_ in (''long'', ''integer'') left join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' and Alert.type_ = ''string''    inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_ where hiproinst.start_time_   between cast(:StartDate as timestamp) and cast(:EndDate as timestamp)   and task.assignee_ is not null and hiproinst.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) and hiproinst.tenant_id_= :tenantidstr and  task.tenant_id_= :tenantidstr limit 15000",
        "Unclaimed": "select task.name_ as \\"Stage\\", task.assignee_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\",null  as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" ,null as  \\"Closed By\\"  from camunda.act_ru_task task left join  camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_ left join camunda.act_ru_variable payer on payer.proc_inst_id_ = task.proc_inst_id_ and payer.name_ = ''payer'' and payer.type_ = ''string'' left join camunda.act_ru_variable payee on payee.proc_inst_id_ = task.proc_inst_id_ and payee.name_ = ''payee'' and payee.type_ = ''string'' left join camunda.act_ru_variable  TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' and TransactionAmount.type_ = ''double'' left join  camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' and TicketID.type_ in (''long'', ''integer'') left join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' and Alert.type_ = ''string''    inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_ where hiproinst.start_time_   between cast(:StartDate as timestamp) and cast(:EndDate as timestamp)  and task.assignee_ is null and hiproinst.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) and hiproinst.tenant_id_= :tenantidstr limit 15000",
        "All": "select CASE WHEN  hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN  closedby.assignee_ is not null THEN clsuser.email_ ELSE ''Auto Closed'' END ELSE null END as \\"Closed By\\", hiproinst.end_time_  as  \\"Closed Date\\", CASE WHEN  hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_  as  \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' then ''Closed'' WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN  task.assignee_ is not null THEN oplog.create_time_ ELSE null END  as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" from camunda.act_hi_procinst hiproinst left join camunda.act_re_procdef pdef on pdef.id_ = hiproinst.proc_def_id_ left join camunda.act_ru_task task on task.proc_inst_id_ = hiproinst.proc_inst_id_ left join camunda.act_id_user cuser on cuser.id_ = task.assignee_ left join camunda.act_hi_varinst oplog on oplog.id_ = (select id_ from camunda.act_hi_varinst where proc_inst_id_ = task.proc_inst_id_ and name_ = ''userActivity'' and var_type_ = ''string'' order by create_time_ desc limit 1) left join camunda.act_hi_taskinst closedby on closedby.id_ = (select id_ from camunda.act_hi_taskinst where proc_inst_id_ = hiproinst.proc_inst_id_ order by end_time_ desc limit 1) left join camunda.act_id_user clsuser on clsuser.id_=closedby.assignee_ left join camunda.act_hi_varinst payer on payer.proc_inst_id_ = hiproinst.proc_inst_id_ and payer.name_ = ''payer'' and payer.var_type_ = ''string'' left join camunda.act_hi_varinst payee on payee.proc_inst_id_ = hiproinst.proc_inst_id_ and payee.name_ = ''payee'' and payee.var_type_ = ''string'' left join camunda.act_hi_varinst  TransactionAmount on TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' and TransactionAmount.var_type_ = ''double'' left join camunda.act_hi_varinst  TicketID on TicketID.proc_inst_id_ = hiproinst.proc_inst_id_ and TicketID.name_ = ''TicketID'' and TicketID.var_type_ in (''long'', ''integer'')  left join camunda.act_hi_varinst Alert on Alert.proc_inst_id_ = hiproinst.proc_inst_id_ and Alert.name_ = ''Alert'' and Alert.var_type_ = ''string''   where hiproinst.start_time_   between cast(:StartDate as timestamp) and cast(:EndDate as timestamp) and hiproinst.state_ != ''EXTERNALLY_TERMINATED'' and hiproinst.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) and hiproinst.tenant_id_= :tenantidstr limit 15000",
        "Closed": "select CASE WHEN  hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN  closedby.assignee_ is not null THEN clsuser.email_ ELSE ''Auto Closed'' END ELSE null END as \\"Closed By\\", hiproinst.end_time_  as  \\"Closed Date\\", CASE WHEN  hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END as \\"Stage\\", task.assignee_ as \\"Claimed By\\", hiproinst.start_time_  as  \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' then ''Closed'' WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN  task.assignee_ is not null THEN oplog.create_time_ ELSE null END  as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" from camunda.act_hi_procinst hiproinst left join camunda.act_re_procdef pdef on pdef.id_ = hiproinst.proc_def_id_ left join camunda.act_ru_task task on task.proc_inst_id_ = hiproinst.proc_inst_id_ left join camunda.act_hi_varinst oplog on oplog.id_ = (select id_ from camunda.act_hi_varinst where proc_inst_id_ = task.proc_inst_id_ and name_ = ''userActivity'' and var_type_ = ''string'' order by create_time_ desc limit 1) left join camunda.act_hi_taskinst closedby on closedby.id_ = (select id_ from camunda.act_hi_taskinst where proc_inst_id_ = hiproinst.proc_inst_id_ order by end_time_ desc limit 1) left join camunda.act_id_user clsuser on closedby.assignee_ = clsuser.id_ left join camunda.act_hi_varinst payer on payer.proc_inst_id_ = hiproinst.proc_inst_id_ and payer.name_ = ''payer'' and payer.var_type_ = ''string'' left join camunda.act_hi_varinst payee on payee.proc_inst_id_ = hiproinst.proc_inst_id_ and payee.name_ = ''payee'' and payee.var_type_ = ''string'' left join camunda.act_hi_varinst  TransactionAmount on TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' and TransactionAmount.var_type_ = ''double'' left join camunda.act_hi_varinst  TicketID on TicketID.proc_inst_id_ = hiproinst.proc_inst_id_ and TicketID.name_ = ''TicketID'' and TicketID.var_type_ in (''long'', ''integer'')  left join camunda.act_hi_varinst Alert on Alert.proc_inst_id_ = hiproinst.proc_inst_id_ and Alert.name_ = ''Alert'' and Alert.var_type_ = ''string''   where hiproinst.start_time_   between cast(:StartDate as timestamp) and cast(:EndDate as timestamp) and hiproinst.state_ = ''COMPLETED'' and hiproinst.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) and hiproinst.tenant_id_= :tenantidstr limit 15000"
    },
    "Other": {
        "Claimed": "select task.name_ as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN  task.assignee_ is not null THEN oplog.create_time_ ELSE null END as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" ,null as  \\"Closed By\\"  from camunda.act_ru_task task left join  camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_ left join camunda.act_id_user cuser on task.assignee_ = cuser.id_ left join camunda.act_hi_varinst oplog on oplog.id_ = (select id_ from camunda.act_hi_varinst where proc_inst_id_ = task.proc_inst_id_ and name_ = ''userActivity'' and var_type_ = ''string'' order by create_time_ desc limit 1) left join camunda.act_ru_variable payer on payer.proc_inst_id_ = task.proc_inst_id_ and payer.name_ = ''payer'' and payer.type_ = ''string'' left join camunda.act_ru_variable payee on payee.proc_inst_id_ = task.proc_inst_id_ and payee.name_ = ''payee'' and payee.type_ = ''string'' left join camunda.act_ru_variable  TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' and TransactionAmount.type_ = ''double'' left join  camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' and TicketID.type_ in (''long'', ''integer'') left join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' and Alert.type_ = ''string''    inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_ where hiproinst.start_time_   between cast(:StartDate as timestamp) and cast(:EndDate as timestamp) and task.proc_def_id_ in (SELECT id_ FROM camunda.act_re_procdef where key_ = :CaseType and tenant_id_= :tenantidstr) and task.assignee_ is not null and  task.tenant_id_= :tenantidstr limit 15000",
        "Unclaimed": "select task.name_ as \\"Stage\\", task.assignee_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", null as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" ,null as  \\"Closed By\\"  from camunda.act_ru_task task left join  camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_ left join camunda.act_ru_variable payer on payer.proc_inst_id_ = task.proc_inst_id_ and payer.name_ = ''payer'' and payer.type_ = ''string'' left join camunda.act_ru_variable payee on payee.proc_inst_id_ = task.proc_inst_id_ and payee.name_ = ''payee'' and payee.type_ = ''string'' left join camunda.act_ru_variable  TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' and TransactionAmount.type_ = ''double'' left join  camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' and TicketID.type_ in (''long'', ''integer'') left join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' and Alert.type_ = ''string''    inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_ where hiproinst.start_time_   between cast(:StartDate as timestamp) and cast(:EndDate as timestamp) and task.proc_def_id_ in (SELECT id_ FROM camunda.act_re_procdef where key_ = :CaseType and tenant_id_= :tenantidstr) and task.assignee_ is null and  task.tenant_id_= :tenantidstr limit 15000",
        "All": "select CASE WHEN  hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN  closedby.assignee_ is not null THEN clsuser.email_ ELSE ''Auto Closed'' END ELSE null END as \\"Closed By\\", hiproinst.end_time_  as  \\"Closed Date\\", CASE WHEN  hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_  as  \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' then ''Closed'' WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN task.assignee_ is not null THEN oplog.create_time_ ELSE null END  as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" from camunda.act_hi_procinst hiproinst left join camunda.act_re_procdef pdef on pdef.id_ = hiproinst.proc_def_id_ left join camunda.act_ru_task task on task.proc_inst_id_ = hiproinst.proc_inst_id_ left join camunda.act_id_user cuser on cuser.id_=task.assignee_ left join camunda.act_hi_varinst oplog on oplog.id_ = (select id_ from camunda.act_hi_varinst where proc_inst_id_ = task.proc_inst_id_ and name_ = ''userActivity'' and var_type_ = ''string'' order by create_time_ desc limit 1) left join camunda.act_hi_taskinst closedby on closedby.id_ = (select id_ from camunda.act_hi_taskinst where proc_inst_id_ = hiproinst.proc_inst_id_ order by end_time_ desc limit 1) left join camunda.act_id_user clsuser on clsuser.id_=closedby.assignee_ left join camunda.act_hi_varinst payer on payer.proc_inst_id_ = hiproinst.proc_inst_id_ and payer.name_ = ''payer'' and payer.var_type_ = ''string'' left join camunda.act_hi_varinst payee on payee.proc_inst_id_ = hiproinst.proc_inst_id_ and payee.name_ = ''payee'' and payee.var_type_ = ''string'' left join camunda.act_hi_varinst  TransactionAmount on TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' and TransactionAmount.var_type_ = ''double'' left join camunda.act_hi_varinst  TicketID on TicketID.proc_inst_id_ = hiproinst.proc_inst_id_ and TicketID.name_ = ''TicketID'' and TicketID.var_type_ in (''long'', ''integer'')  left join camunda.act_hi_varinst Alert on Alert.proc_inst_id_ = hiproinst.proc_inst_id_ and Alert.name_ = ''Alert'' and Alert.var_type_ = ''string''   where hiproinst.start_time_   between cast(:StartDate as timestamp) and cast(:EndDate as timestamp) and hiproinst.state_ != ''EXTERNALLY_TERMINATED'' and hiproinst.proc_def_key_ = :CaseType and hiproinst.tenant_id_= :tenantidstr limit 15000",
        "Closed": "select CASE WHEN  hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN  closedby.assignee_ is not null THEN clsuser.email_ ELSE ''Auto Closed'' END ELSE null END as \\"Closed By\\", hiproinst.end_time_  as  \\"Closed Date\\", CASE WHEN  hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END as \\"Stage\\", task.assignee_ as \\"Claimed By\\", hiproinst.start_time_  as  \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' then ''Closed'' WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN task.assignee_ is not null THEN oplog.create_time_ ELSE null END  as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" from camunda.act_hi_procinst hiproinst left join camunda.act_re_procdef pdef on pdef.id_ = hiproinst.proc_def_id_ left join camunda.act_ru_task task on task.proc_inst_id_ = hiproinst.proc_inst_id_ left join camunda.act_hi_varinst oplog on oplog.id_ = (select id_ from camunda.act_hi_varinst where proc_inst_id_ = task.proc_inst_id_ and name_ = ''userActivity'' and var_type_ = ''string'' order by create_time_ desc limit 1) left join camunda.act_hi_taskinst closedby on closedby.id_ = (select id_ from camunda.act_hi_taskinst where proc_inst_id_ = hiproinst.proc_inst_id_ order by end_time_ desc limit 1) left join camunda.act_id_user clsuser on clsuser.id_ = closedby.assignee_ left join camunda.act_hi_varinst payer on payer.proc_inst_id_ = hiproinst.proc_inst_id_ and payer.name_ = ''payer'' and payer.var_type_ = ''string'' left join camunda.act_hi_varinst payee on payee.proc_inst_id_ = hiproinst.proc_inst_id_ and payee.name_ = ''payee'' and payee.var_type_ = ''string'' left join camunda.act_hi_varinst  TransactionAmount on TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' and 